// Read-only access to the versioned NASA-derived products used by the shell routes.
// Nothing here invents a value: missing data stays NaN and is shown as "N/D" by the views.
// Source of truth: this .ts file. data.js is generated by `npm --prefix web run build:ts`.
// @ts-ignore TS7016: JS module without types
import { SiteSeries, HOUR_MS } from "../lab/data.js";
// @ts-ignore TS7016
import { TerrainGrid } from "../lab/terrain.js";
let sitesP = null;
const seriesCache = new Map(), tileCache = new Map();
let regionP = null;
export { HOUR_MS };
/** data/sites.json → { sites, features, window:{start,end,hours}, raw }. Coordinates and sources are used as-is. */
export function loadSites() {
    if (!sitesP)
        sitesP = fetch("./data/sites.json").then(r => { if (!r.ok)
            throw new Error("data/sites.json HTTP " + r.status); return r.json(); })
            .then((raw) => {
            const start = Date.parse(raw.series_window.start_utc);
            return { raw, sites: raw.sites, features: raw.features || [], window: { start, hours: raw.series_window.hours, end: start + (raw.series_window.hours - 1) * HOUR_MS } };
        });
    return sitesP;
}
export function siteSeries(site) {
    if (!seriesCache.has(site.id))
        seriesCache.set(site.id, SiteSeries.load("./data/" + site.series));
    return seriesCache.get(site.id);
}
export function siteTile(site) {
    if (!tileCache.has(site.id))
        tileCache.set(site.id, TerrainGrid.load("./data/" + site.local_tile));
    return tileCache.get(site.id);
}
export function regionGrid() {
    if (!regionP)
        regionP = TerrainGrid.load("./data/region/south_pole_400m");
    return regionP;
}
/** Default scenario time: now (rounded to the hour) if inside the computed window, else its start. */
export function defaultTime(win) {
    const now = Math.floor(Date.now() / HOUR_MS) * HOUR_MS;
    return now >= win.start && now <= win.end ? now : win.start;
}
/** Parse ?t= (ISO date/time, UTC) into ms inside the window, else the default time. */
export function timeFromQuery(query, win) {
    const t = query.t ? Date.parse(query.t.length <= 16 ? query.t + (query.t.length === 10 ? "T00:00Z" : "Z") : query.t) : NaN;
    return Number.isFinite(t) && t >= win.start && t <= win.end ? Math.floor(t / HOUR_MS) * HOUR_MS : defaultTime(win);
}
export const isoHour = (t) => new Date(t).toISOString().slice(0, 13) + ":00Z";
export const fmtDate = (t) => new Date(t).toLocaleString("pt-BR", { timeZone: "UTC", day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) + " UTC";
/**
 * Window metrics for one site from the hourly LOLA+SPICE series (disc centre vs terrain horizon).
 * Returns { status:"COMPUTED", sunPct, earthPct, bothPct, longestDarkH, longestBlackoutH, nights, losses,
 *           nextSunsetH, darkStart } or { status:"NOT_COMPUTED", reason }.
 */
export function windowMetrics(series, t0, hours) {
    const w = series.window(t0, hours);
    if (w.status !== "COMPUTED")
        return w;
    const i0 = Math.ceil((t0 - series.start) / HOUR_MS);
    let nights = 0, losses = 0, run = 0, best = 0, bestStart = -1, cur = -1;
    for (let i = i0; i < i0 + hours; i++) {
        const s = series.sunMargin[i] >= 0;
        if (!s) {
            if (run === 0) {
                nights++;
                cur = i;
            }
            run++;
            if (run > best) {
                best = run;
                bestStart = cur;
            }
        }
        else
            run = 0;
        if (series.earthMargin[i] < 0 && (i === i0 || series.earthMargin[i - 1] >= 0))
            losses++;
    }
    const next = series.nextChange(t0, "sun");
    return { ...w, nights, losses, darkStart: bestStart >= 0 ? series.start + bestStart * HOUR_MS : null,
        sunUpNow: series.sunMargin[series.index(t0)] >= 0, nextChangeH: next.status === "COMPUTED" ? next.hours : NaN };
}
/** Per-day fraction of hours with the body visible (for timelines). NaN outside the data. */
export function dailyFractions(series, t0, days, body) {
    const m = body === "sun" ? series.sunMargin : series.earthMargin;
    const i0 = Math.ceil((t0 - series.start) / HOUR_MS), out = [];
    for (let d = 0; d < days; d++) {
        let n = 0, v = 0;
        for (let h = 0; h < 24; h++) {
            const i = i0 + d * 24 + h;
            if (i >= 0 && i < series.count) {
                n++;
                if (m[i] >= 0)
                    v++;
            }
        }
        out.push(n ? v / n : NaN);
    }
    return out;
}
/** Hourly CSV rows for export (Prova layer). */
export function hourlyRows(series, t0, hours) {
    const i0 = Math.ceil((t0 - series.start) / HOUR_MS), rows = [];
    for (let i = Math.max(0, i0); i < Math.min(series.count, i0 + hours); i++) {
        rows.push([new Date(series.start + i * HOUR_MS).toISOString(), series.s.sunAz[i], series.s.sunEl[i], series.sunMargin[i], series.s.earthAz[i], series.s.earthEl[i], series.earthMargin[i]]);
    }
    return rows;
}
